from itertools import permutations

def largest_empty_square(n, perm):
    """For a given permutation (happy config), find the largest k such that
    there exists an empty k×k contiguous square."""
    # perm[i] = column of rook in row i (0-indexed)
    # For each k from n down to 1, check if there's an empty k×k contiguous square
    for k in range(n, 0, -1):
        # Try all k×k contiguous squares
        for r in range(n - k + 1):
            for c in range(n - k + 1):
                # Check if square with rows [r, r+k-1] and cols [c, c+k-1] is empty
                empty = True
                for i in range(r, r + k):
                    if c <= perm[i] <= c + k - 1:
                        empty = False
                        break
                if empty:
                    return k
    return 0

def solve(n):
    """Find the largest k that works for ALL permutations of size n."""
    worst = n  # worst case (minimum over all permutations)
    for perm in permutations(range(n)):
        k = largest_empty_square(n, perm)
        worst = min(worst, k)
    return worst

for n in range(2, 9):
    k = solve(n)
    print(f"n={n}: k={k}")
