from itertools import permutations

def largest_empty_square_fast(n, perm):
    """For a given permutation, find the largest k with an empty k×k contiguous square."""
    for k in range(n, 0, -1):
        for r in range(n - k + 1):
            for c in range(n - k + 1):
                empty = True
                for i in range(r, r + k):
                    if c <= perm[i] <= c + k - 1:
                        empty = False
                        break
                if empty:
                    return k
    return 0

def solve_brute(n):
    """Find min over all permutations of largest_empty_square."""
    worst = n
    for perm in permutations(range(n)):
        k = largest_empty_square_fast(n, perm)
        if k < worst:
            worst = k
    return worst

# Compute for n=2 to 8 (already done) and try n=9 with optimization
results = {}
for n in range(2, 9):
    results[n] = solve_brute(n)
    print(f"n={n}: k={results[n]}")

# For n=9, use a different approach: try to find a bad permutation for each k
print("\n--- Using backtracking to find worst permutation ---")

def is_k_hitting_set(S, n, k):
    """Check if set S of size k hits every interval of length k in {0,...,n-1}."""
    S_set = set(S)
    for b in range(n - k + 1):
        interval = set(range(b, b + k))
        if not S_set & interval:
            return False
    return True

def find_bad_perm(n, k):
    """Try to find a permutation where every k consecutive rows map to a k-hitting set.
    Returns the permutation if found, None otherwise."""
    # Precompute all k-hitting sets of size k
    from itertools import combinations
    hitting_sets = []
    for combo in combinations(range(n), k):
        if is_k_hitting_set(combo, n, k):
            hitting_sets.append(frozenset(combo))

    if not hitting_sets:
        return None  # No k-hitting sets exist, so k always works

    hitting_set_of_sets = set(hitting_sets)

    # Backtracking: place values one by one
    perm = [-1] * n
    used = [False] * n

    def backtrack(pos):
        if pos == n:
            return True
        for val in range(n):
            if used[val]:
                continue
            perm[pos] = val
            used[val] = True

            # Check constraint: if we have at least k elements placed,
            # check if the last k form a hitting set
            valid = True
            if pos >= k - 1:
                window = frozenset(perm[pos - k + 1 : pos + 1])
                if window not in hitting_set_of_sets:
                    valid = False

            if valid and backtrack(pos + 1):
                return True

            used[val] = False
            perm[pos] = -1
        return False

    if backtrack(0):
        return tuple(perm)
    return None

for n in range(2, 15):
    # Find largest k such that no bad permutation exists
    best_k = 0
    for k in range(1, n + 1):
        bad = find_bad_perm(n, k)
        if bad is None:
            best_k = k
        else:
            # Bad permutation exists for this k, so k doesn't work
            break
    print(f"n={n}: k={best_k}")
